class LmdbStatementPatternCardinalitySourceTest {

	@Test
	void directDistinctProbePreservesCallerPattern() {
		long identity = -780L;
		TripleStore tripleStore = mock(TripleStore.class, invocation -> {
			if (invocation.getMethod().getReturnType() == OptionalLong.class) {
				return OptionalLong.of(7L);
			}
			return Answers.RETURNS_DEFAULTS.answer(invocation);
		});
		StatementPattern pattern = new StatementPattern(new Var("s"), new Var("p"), new Var("o"));
		LmdbStatementPatternCardinalitySource source = new LmdbStatementPatternCardinalitySource(
				mock(ValueStore.class), tripleStore, identity);

		try {
			assertEquals(7.0d, source.estimateDistinct(pattern, "s", 32).orElseThrow());
			assertNull(pattern.getStringMetricPlanned(TelemetryMetricNames.PLANNED_DISTINCT_REQUIREMENT_VARS));
			assertNull(pattern.getStringMetricPlanned(TelemetryMetricNames.PLANNED_DISTINCT_REQUIREMENT_SOURCE));
		} finally {
			LmdbStatementPatternCardinalitySource.evictStore(identity);
		}
	}

	@Test
	void ordinaryTierRepeatedVariablesNeverTriggerAnExactLmdbScan() throws Exception {
		TripleStore tripleStore = mock(TripleStore.class);
		when(tripleStore.getDataRevision()).thenReturn(13L);
		when(tripleStore.planningCardinality(anyLong(), anyLong(), anyLong(), anyLong())).thenReturn(81.0d);
		LmdbStatementPatternCardinalitySource source = new LmdbStatementPatternCardinalitySource(
				mock(ValueStore.class), tripleStore);
		StatementPattern repeated = new StatementPattern(new Var("x"), new Var("p"), new Var("x"));

		assertEquals(81.0d, source.estimateForPlanning(repeated));
		verify(tripleStore).planningCardinality(LmdbValue.UNKNOWN_ID, LmdbValue.UNKNOWN_ID,
				LmdbValue.UNKNOWN_ID, LmdbValue.UNKNOWN_ID);
		verify(tripleStore, never()).repeatedVariableCardinality(anyLong(), anyLong(), anyLong(), anyLong(), anyInt());
	}

	@Test
	void sharedCacheEntriesFromAnotherStoreWithEqualIdentityAreNeverServed(@TempDir Path tempDir) throws Exception {
		// Colliding identities cross-serve cached counts — this is the aliasing the identityHashCode scheme
		// permitted between distinct stores (LMDB value ids are small sequential longs, so ids overlap freely).
		long collidingIdentity = -777L;
		TripleStore first = mock(TripleStore.class);
		when(first.getDataRevision()).thenReturn(3L);
		when(first.planningCardinality(anyLong(), anyLong(), anyLong(), anyLong())).thenReturn(81.0d);
		TripleStore second = mock(TripleStore.class);
		when(second.getDataRevision()).thenReturn(3L);
		when(second.planningCardinality(anyLong(), anyLong(), anyLong(), anyLong())).thenReturn(999.0d);
		StatementPattern pattern = new StatementPattern(new Var("s"), new Var("p"), new Var("o"));

		new LmdbStatementPatternCardinalitySource(mock(ValueStore.class), first, collidingIdentity)
				.estimateForPlanning(pattern);
		double crossServed = new LmdbStatementPatternCardinalitySource(mock(ValueStore.class), second,
				collidingIdentity).estimateForPlanning(pattern);
		assertEquals(81.0d, crossServed, "colliding identities must cross-serve, or this test guards nothing");

		// The production identity is a JVM-unique counter per TripleStore instance, so real stores can never
		// collide the way identityHashCode could.
		File firstDir = tempDir.resolve("first").toFile();
		File secondDir = tempDir.resolve("second").toFile();
		firstDir.mkdirs();
		secondDir.mkdirs();
		TripleStore realFirst = new TripleStore(firstDir, new LmdbStoreConfig("spoc,posc"), null);
		try {
			TripleStore realSecond = new TripleStore(secondDir, new LmdbStoreConfig("spoc,posc"), null);
			try {
				assertNotEquals(realFirst.instanceId(), realSecond.instanceId(),
						"Every TripleStore instance must get a distinct shared-cache identity");
				assertTrue(realSecond.instanceId() > realFirst.instanceId(),
						"Identities must be monotonic so a closed store's identity is never reissued");
			} finally {
				realSecond.close();
			}
		} finally {
			realFirst.close();
		}
	}

	@Test
	void closedStoreEntriesAreEvictedFromSharedCaches() throws Exception {
		long identity = -778L;
		TripleStore tripleStore = mock(TripleStore.class);
		when(tripleStore.getDataRevision()).thenReturn(5L);
		when(tripleStore.planningCardinality(anyLong(), anyLong(), anyLong(), anyLong())).thenReturn(17.0d, 23.0d);
		LmdbStatementPatternCardinalitySource source = new LmdbStatementPatternCardinalitySource(
				mock(ValueStore.class), tripleStore, identity);
		StatementPattern pattern = new StatementPattern(new Var("s"), new Var("p"), new Var("o"));

		assertEquals(17.0d, source.estimateForPlanning(pattern));
		assertEquals(17.0d, source.estimateForPlanning(pattern), "second read must come from the shared cache");

		LmdbStatementPatternCardinalitySource.evictStore(identity);

		assertEquals(23.0d, source.estimateForPlanning(pattern),
				"eviction must drop the closed store's entries so the next read recomputes");
	}

	@Test
	void commitDuringCardinalityComputationIsNotCachedUnderThePreCommitRevision() throws Exception {
		long identity = -779L;
		java.util.concurrent.atomic.AtomicLong revision = new java.util.concurrent.atomic.AtomicLong(7L);
		java.util.concurrent.atomic.AtomicInteger computes = new java.util.concurrent.atomic.AtomicInteger();
		TripleStore tripleStore = mock(TripleStore.class);
		when(tripleStore.getDataRevision()).thenAnswer(invocation -> revision.get());
		// The first count races with a commit: the revision moves to 8 mid-computation and the returned count
		// reflects the post-commit data. The true revision-7 count is 42.
		when(tripleStore.planningCardinality(anyLong(), anyLong(), anyLong(), anyLong())).thenAnswer(invocation -> {
			if (computes.incrementAndGet() == 1) {
				revision.set(8L);
				return 500.0d;
			}
			return 42.0d;
		});
		LmdbStatementPatternCardinalitySource source = new LmdbStatementPatternCardinalitySource(
				mock(ValueStore.class), tripleStore, identity);
		StatementPattern pattern = new StatementPattern(new Var("s"), new Var("p"), new Var("o"));

		assertEquals(500.0d, source.estimateForPlanning(pattern), "the raced value itself is still returned");

		// A concurrent planner whose revision read interleaved before the commit must not be served the
		// post-commit count under the pre-commit revision key.
		revision.set(7L);
		assertEquals(42.0d, source.estimateForPlanning(pattern),
				"a value computed after a mid-flight commit must not be cached under the pre-commit revision");
	}
}
